// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, uint256 seed) public {
        vm.assume(depositAmount > 0 && depositAmount <= 1000 ether);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);
        address caller = address(uint160(uint256(keccak256(abi.encode(seed)))));
        vm.assume(caller != address(0));

        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        vm.deal(caller, 0);
        uint256 balanceBefore = caller.balance;
        vm.prank(caller);
        c.withdrawAll();
        uint256 balanceAfter = caller.balance;

        assertTrue(balanceAfter - balanceBefore == depositAmount);
    }
}
